import {goodsLocation} from './goods-inventory.js?v=babbc3d3950e';
import {industryRegistry} from './simulation-registry.js?v=babbc3d3950e';
// Read-only view of the active economy. No orders, grants or market refreshes.
export function portEconomicInfo(economy,portId,{world=null,time=0,harbor=null,knowledge=[]}={}){
 const market=economy.getMarketSnapshot(portId),treasury=economy.getPortTreasury(portId),book=economy.getFundedMarket(portId),local=economy.getIndustryAccounts().filter(i=>i.portId===portId),owners=new Set([treasury.id,...local.map(i=>i.id),...economy.getMarketBuyers().filter(b=>b.portId===portId).map(b=>b.accountId)]),allGoods=economy.getGoodsSnapshot().records;
 const industries=local.map(i=>{const d={display_name:i.definition.name,inputs:i.definition.recipe.inputs.map(r=>({commodity_id:r.commodityId,quantity_per_tick:r.quantity})),outputs:i.definition.recipe.outputs.map(r=>({commodity_id:r.commodityId,quantity_per_tick:r.quantity}))},goods=allGoods.filter(r=>r.ownerAccountId===i.id),internal=goods.filter(r=>r.location===goodsLocation('INDUSTRY',i.instanceId??i.account.ownerId));return {...i,instanceId:i.owner,name:d.display_name,manufacturing:i.definition,productionMode:i.productionMode??'NOT_ACTIVATED',industrialProduction:economy.getIndustryProduction(i.id)[0],industrialProcurement:economy.getIndustryProcurement(i.id)[0],supplierCoverage:economy.getIndustrySupplyDiagnostics(i.id)[0],productionHistory:economy.getIndustryProductionHistory(i.id).slice(-20),inputs:d.inputs,outputs:d.outputs,goods,ready:d.inputs.every(input=>internal.filter(r=>r.commodityId===input.commodity_id&&!r.reservationId).reduce((n,r)=>n+r.quantity,0)>=input.quantity_per_tick)};});
 const primary=(world?.industries??[]).filter(i=>i.portId===portId&&industryRegistry.has(i.type)&&!industryRegistry.get(i.type).inputs.length).map(i=>({id:i.id??i.tileIndex,type:i.type,name:industryRegistry.get(i.type).display_name,outputs:industryRegistry.get(i.type).outputs}));
 const source=world?.ports?.find(p=>p.id===portId),meta=source?{population:source.population,capacity:source.capacity,prosperity:source.prosperity,colonyName:source.colonyName,settlementType:source.settlementType,factionName:source.factionName}:{};
 const receipts=economy.getFinancialSnapshot().transactions.filter(r=>owners.has(r.payerId)||(r.debits??[]).some(a=>owners.has(a.accountId))||(r.credits??[]).some(a=>owners.has(a.accountId))).slice(-20);
 const trades=economy.getTradeHistory().filter(t=>owners.has(t.buyerAccountId)||owners.has(t.sellerAccountId)||t.sourceLocation===goodsLocation('MARKET',portId)).slice(-30);
 return structuredClone({portId,name:market.name,faction:market.faction,tick:market.tick,time,meta,treasury,industries,primary,worldKnowledge:knowledge,construction:economy.getIndustryProjects(portId),investments:economy.getIndustryInvestments(portId),unavailableSuppliers:economy.getIndustryDefinitions().filter(d=>d.manufacturing).map(d=>({typeId:d.id,missingInputs:d.inputs.filter(input=>!economy.getIndustryDefinitions().some(s=>s.outputs.some(o=>o.commodity_id===input.commodity_id))).map(input=>input.commodity_id)})).filter(d=>d.missingInputs.length),procurement:economy.getMarketBuyers().filter(b=>b.portId===portId).map(b=>({...b,account:economy.accounts.inspect(b.accountId)})),stocks:market.stocks,orders:book.orders,offers:book.offers,transfers:book.transfers,receipts,goods:allGoods.filter(r=>owners.has(r.ownerAccountId)||r.location===goodsLocation('MARKET',portId)),trades,workerShare:economy.getRevenueRules().manufacturingWorkerShare,harbor:harbor?.manager(portId)?harbor.queueStats(portId):null});
}
export function portCargoHistories(history,commodityIds,portId){return commodityIds.map(id=>{const h=history.snapshot(id,{portId}),port=h.ports.find(p=>p.id===portId);if(!port)throw RangeError('Unknown port');return {...h,ports:[port]};});}
